"""Synthetic lead-qualification data. Generated by a seeded script; NOT real; never a headline claim.

The gold score is computed from the attributes that were written into the text, so the label is
exactly recoverable from the input. That makes this a plumbing/rubric-following check, not evidence
about real-world lead quality.
"""

from __future__ import annotations

import random
from typing import Any

from jev_bench.tasks import Example

ROLES = [("CTO", 2), ("VP Engineering", 2), ("Head of Operations", 1), ("Software Engineer", 0), ("Student", -1)]
SIZES = [
    ("a 5-person startup", 0),
    ("a 60-person company", 1),
    ("a 400-person company", 2),
    ("an enterprise of 5,000+ staff", 3),
]
BUDGETS = [
    ("has no budget yet", -1),
    ("has budget approved for this quarter", 2),
    ("is exploring options and may fund it next year", 0),
]
TIMELINES = [("wants to start within 30 days", 2), ("is looking at the next 6 months", 1), ("has no timeline", 0)]


# The rubric states the scoring rules, so this task checks rubric-following, not sales judgement.
LEAD_RUBRIC = (
    "Score this sales enquiry by adding points, then map the total to a level. "
    "Role: CTO or VP Engineering +2, Head of Operations +1, Software Engineer 0, Student -1. "
    "Company size: 5-person +0, 60-person +1, 400-person +2, 5,000+ staff +3. "
    "Budget: none -1, approved this quarter +2, exploring/next year 0. "
    "Timeline: within 30 days +2, within 6 months +1, none 0. "
    "Total 1 or less = level 0, 2 to 3 = level 1, 4 to 6 = level 2, 7 or more = level 3."
)


def _score(points: int) -> int:
    """0 = poor fit, 1 = nurture, 2 = good fit, 3 = hot."""
    return 0 if points <= 1 else 1 if points <= 3 else 2 if points <= 6 else 3


def make_lead(rng: random.Random) -> tuple[str, int]:
    role, rp = rng.choice(ROLES)
    size, sp = rng.choice(SIZES)
    budget, bp = rng.choice(BUDGETS)
    timeline, tp = rng.choice(TIMELINES)
    text = (
        f"Inbound enquiry from a {role} at {size}. They ask about automating document triage. "
        f"The contact {budget} and {timeline}."
    )
    return text, _score(rp + sp + bp + tp)


def load_leads(limit: int, seed: int) -> tuple[list[Example], dict[str, Any]]:
    rng = random.Random(seed)
    n = min(limit, 5000)
    items = []
    for i in range(n):
        text, label = make_lead(rng)
        items.append(Example(f"{i:05d}", text, label))
    return items, {"dataset": "synthetic-leads", "split": "generated", "revision": f"seed{seed}", "pool": n}
